/* TSZ LP R168 Bundlevero. Three fictional purchase plans. No persistence, network, media or analytics. */
(()=>{'use strict';
const ID='tsz-bv168',APP_ID='6822927747';if(document.getElementById(ID))return;
const L={
 ja:{eyebrow:'BUNDLEVERO / 買い方を比べる',demo:'ページ内の架空例',title:'セットが安いとは、限らない。',intro:'単品・固定価格セット・「持っていない分だけ」のセット完成割引。持っている商品を変えるだけで、最安の買い方が逆転します。',choose:'商品の所有状況',owned:'所有済み',items:['ゲームA','ゲームB','ゲームC'],fixed:'固定価格セット（全3商品）',discount:'セット完成割引（不足分）',rates:'割引率 (%)',prices:'単品価格',plans:'3通りの支払額',winner:'この条件で最も安い案',names:['単品で購入','固定セットで購入','セット完成割引を利用'],details:['持っていない商品の単品合計','所有状況に関係なく全品セットを買う','不足分の合計に設定割引を適用'],saving:'単品との差額',same:'最安が同額の案があります。',reason:'所有状況・価格・割引率を変えると結果が更新されます。',free:'追加購入なし',reset:'最初の条件に戻す',invalid:'価格は0以上100,000以下、割引率は0〜90にしてください。',note:'これは計算方法を示す架空の3商品・3条件によるLP用デモです。実際の店舗・セット規約、在庫や価格は取得しません。税・手数料・為替換算は含まず、実アプリの最適化アルゴリズムや最安保証を再現しません。入力は保存・送信しません。',short:'最初は固定セットが最安。「ゲームAは持っている」に切り替えると、セット完成割引が最安になります。'},
 en:{eyebrow:'BUNDLEVERO / COMPARE YOUR PLAN',demo:'Fictional on-page sample',title:'A bundle is not always cheaper.',intro:'Compare singles, a fixed-price bundle, and a complete-the-set discount on missing items. Already own something? The cheapest plan can change.',choose:'What you already own',owned:'Owned',items:['Game A','Game B','Game C'],fixed:'Fixed bundle (all 3 items)',discount:'Complete-the-set discount',rates:'Discount rate (%)',prices:'Single prices',plans:'Three ways to pay',winner:'Lowest total for these inputs',names:['Buy singles','Buy fixed bundle','Complete the set'],details:['Total for all items not owned','Pay for the full bundle, regardless of ownership','Apply the sample discount to missing items'],saving:'Difference vs singles',same:'More than one plan shares the lowest total.',reason:'Edit ownership, price or discount to compare again.',free:'Nothing else to buy',reset:'Restore sample',invalid:'Enter prices between 0 and 100,000 and a discount between 0% and 90%.',note:'Fictional three-item, three-rule website demo only. No live prices, store bundle rules or inventory are fetched. Excludes tax, fees and FX. Does not reproduce the app optimizer or guarantee the globally cheapest plan. Nothing is saved or sent.',short:'At first the fixed bundle wins. Mark Game A as owned and completing the set becomes cheaper.'},
 ar:{eyebrow:'BUNDLEVERO / قارن طرق الشراء',demo:'مثال خيالي في الصفحة',title:'ليست الحزمة الأرخص دائمًا.',intro:'قارن شراء العناصر منفردة وحزمة بسعر ثابت وخصم إكمال المجموعة على العناصر الناقصة. قد يتغير الخيار الأرخص حسب ما تملكه.',choose:'العناصر التي تملكها',owned:'أملكه',items:['اللعبة أ','اللعبة ب','اللعبة ج'],fixed:'حزمة ثابتة (العناصر الثلاثة)',discount:'خصم إكمال المجموعة',rates:'نسبة الخصم (%)',prices:'الأسعار الفردية',plans:'ثلاث طرق للدفع',winner:'أقل مبلغ وفق المدخلات',names:['شراء العناصر منفردة','شراء الحزمة الثابتة','إكمال المجموعة'],details:['مجموع العناصر التي لا تملكها','دفع سعر الحزمة كاملة بغض النظر عن الملكية','خصم تجريبي على العناصر الناقصة'],saving:'الفرق مقارنة بالشراء الفردي',same:'توجد خيارات متساوية في أقل مبلغ.',reason:'غيّر الملكية أو الأسعار أو الخصم للمقارنة.',free:'لا حاجة لشراء إضافي',reset:'إعادة المثال الأول',invalid:'أدخل أسعارًا من 0 إلى 100000 وخصمًا من 0٪ إلى 90٪.',note:'مثال خيالي في صفحة الويب بثلاثة منتجات وشروط مبسطة. لا يجلب الأسعار الحية أو شروط المتاجر أو المخزون. لا يشمل الضرائب والرسوم أو تحويل العملات. لا يحاكي خوارزمية التطبيق ولا يضمن أقل سعر عالميًا. لا يحفظ أو يرسل أي بيانات.',short:'في البداية تكون الحزمة الثابتة أرخص. عندما تضع علامة أنك تملك اللعبة أ، يصبح إكمال المجموعة أرخص.'}
};
const start={prices:[900,1400,1100],owned:[false,false,false],bundle:2500,discount:20};
let state=JSON.parse(JSON.stringify(start)),current='en';
const fmt=n=>Number.isFinite(n)?'$'+n.toLocaleString('en-US',{maximumFractionDigits:2,minimumFractionDigits:0}):'—';
function language(){const sel=document.getElementById('p199-language')?.value||'';const search=new URLSearchParams(location.search).get('lang')||'';const raw=(sel||search||document.documentElement.lang||navigator.language||'en').toLowerCase();return raw.startsWith('ar')?'ar':raw.startsWith('ja')?'ja':'en'}
function mount(){if(document.getElementById(ID))return;let anchor=document.getElementById('overview')||document.querySelector('main')||document.body;let root=document.createElement('section');root.id=ID;root.setAttribute('aria-labelledby','bv168-title');
 root.innerHTML=`<div class="bv168-hero"><div class="bv168-overline"><span data-t="eyebrow"></span><span class="bv168-chip" data-t="demo"></span></div><h2 id="bv168-title" data-t="title"></h2><p data-t="intro"></p></div><div class="bv168-body"><p class="bv168-headline" data-t="short"></p><div class="bv168-layout"><section class="bv168-panel"><h3 data-t="choose"></h3><div class="bv168-grid3" id="bv168-products"></div><div class="bv168-conditions"><label class="bv168-field"><span data-t="fixed"></span><input id="bv168-bundle" type="number" min="0" max="100000" step="1" value="2500" inputmode="decimal"></label><label class="bv168-field"><span data-t="discount"></span><input id="bv168-discount" type="number" min="0" max="90" step="1" value="20" inputmode="decimal"></label></div><p class="bv168-help" data-t="reason"></p><p class="bv168-error" id="bv168-error" role="status"></p><div class="bv168-actions"><button type="button" id="bv168-reset" data-t="reset"></button></div></section><section class="bv168-panel"><h3 data-t="plans"></h3><div class="bv168-winner"><small data-t="winner"></small><strong id="bv168-winning"></strong><p id="bv168-win-name"></p></div><div id="bv168-plans" class="bv168-plans"></div><p class="bv168-summary" id="bv168-saving" aria-live="polite"></p></section></div><p class="bv168-note" data-t="note"></p></div>`;
 anchor.insertAdjacentElement('afterend',root);const $=s=>root.querySelector(s);
 function products(w){const el=$('#bv168-products');el.innerHTML='';for(let i=0;i<3;i++){const row=document.createElement('div');row.className='bv168-product';const label=document.createElement('label');const cb=document.createElement('input');cb.type='checkbox';cb.dataset.index=String(i);cb.checked=state.owned[i];cb.setAttribute('aria-label',w.items[i]+' '+w.owned);const span=document.createElement('span');span.textContent=w.items[i]+' · '+w.owned;label.append(cb,span);const value=document.createElement('input');value.type='number';value.min='0';value.max='100000';value.step='1';value.inputMode='decimal';value.className='bv168-price';value.dataset.price=String(i);value.value=String(state.prices[i]);value.setAttribute('aria-label',w.items[i]+' '+w.prices);row.append(label,value);el.append(row)}}
 function render(){let lang=language(),w=L[lang];current=lang;root.dir=lang==='ar'?'rtl':'ltr';root.lang=lang;root.querySelectorAll('[data-t]').forEach(el=>{el.textContent=w[el.dataset.t]||''});products(w);$('#bv168-bundle').value=String(state.bundle);$('#bv168-discount').value=String(state.discount);const singles=state.prices.reduce((s,v,i)=>s+(state.owned[i]?0:v),0);const bundle=state.bundle;const complete=Math.round(singles*(100-state.discount))/100;let arr=[singles,bundle,complete];const isValid=[...state.prices,state.bundle,state.discount].every(Number.isFinite)&&[...state.prices,state.bundle].every(v=>v>=0&&v<=100000)&&state.discount>=0&&state.discount<=90;let plans=$('#bv168-plans');plans.replaceChildren();if(!isValid){$('#bv168-error').textContent=w.invalid;$('#bv168-winning').textContent='—';$('#bv168-win-name').textContent='';$('#bv168-saving').textContent='';return}$('#bv168-error').textContent='';const min=Math.min(...arr);let best=arr.findIndex(n=>Math.abs(n-min)<.00001);$('#bv168-winning').textContent=fmt(min);$('#bv168-win-name').textContent=(singles===0?w.free:w.names[best]);arr.forEach((n,i)=>{let row=document.createElement('article');row.className='bv168-plan';row.dataset.plan=String(i);row.dataset.best=String(Math.abs(n-min)<.00001);let text=document.createElement('div'),title=document.createElement('h4'),help=document.createElement('p'),amount=document.createElement('strong');title.textContent=w.names[i];help.textContent=w.details[i];amount.textContent=fmt(n);text.append(title,help);row.append(text,amount);plans.append(row)});let tie=arr.filter(n=>Math.abs(n-min)<.00001).length>1;$('#bv168-saving').textContent=`${w.saving}: ${fmt(Math.max(0,singles-min))}${tie?' · '+w.same:''}`}
 function readInputs(){root.querySelectorAll('input[data-price]').forEach(el=>{state.prices[Number(el.dataset.price)]=el.value.trim()===''?NaN:Number(el.value)});root.querySelectorAll('input[data-index]').forEach(el=>{state.owned[Number(el.dataset.index)]=el.checked});let bv=$('#bv168-bundle'),dv=$('#bv168-discount');state.bundle=bv.value.trim()===''?NaN:Number(bv.value);state.discount=dv.value.trim()===''?NaN:Number(dv.value)}
 // Avoid re-creating focused inputs when editing; only rebuild controls on locale switches or reset.
 function recalc(){const w=L[current],singles=state.prices.reduce((s,v,i)=>s+(state.owned[i]?0:v),0),arr=[singles,state.bundle,Math.round(singles*(100-state.discount))/100];const valid=[...state.prices,state.bundle,state.discount].every(Number.isFinite)&&[...state.prices,state.bundle].every(v=>v>=0&&v<=100000)&&state.discount>=0&&state.discount<=90;$('#bv168-error').textContent=valid?'':w.invalid;const list=$('#bv168-plans');list.replaceChildren();if(!valid){$('#bv168-winning').textContent='—';$('#bv168-win-name').textContent='';$('#bv168-saving').textContent='';return}let min=Math.min(...arr),best=arr.findIndex(n=>Math.abs(n-min)<.00001),tie=arr.filter(n=>Math.abs(n-min)<.00001).length>1;$('#bv168-winning').textContent=fmt(min);$('#bv168-win-name').textContent=singles===0?w.free:w.names[best];arr.forEach((n,i)=>{let row=document.createElement('article');row.className='bv168-plan';row.dataset.plan=String(i);row.dataset.best=String(Math.abs(n-min)<.00001);let text=document.createElement('div'),title=document.createElement('h4'),help=document.createElement('p'),amount=document.createElement('strong');title.textContent=w.names[i];help.textContent=w.details[i];amount.textContent=fmt(n);text.append(title,help);row.append(text,amount);list.append(row)});$('#bv168-saving').textContent=`${w.saving}: ${fmt(Math.max(0,singles-min))}${tie?' · '+w.same:''}`}
 root.addEventListener('input',e=>{if(!(e.target instanceof HTMLInputElement))return;readInputs();recalc()});root.addEventListener('change',e=>{if(!(e.target instanceof HTMLInputElement))return;readInputs();recalc()});$('#bv168-reset').addEventListener('click',()=>{state=JSON.parse(JSON.stringify(start));render()});document.getElementById('p199-language')?.addEventListener('change',render);let prev=language();new MutationObserver(()=>{let nxt=language();if(nxt!==prev){prev=nxt;render()}}).observe(document.documentElement,{attributes:true,attributeFilter:['lang']});render();
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',mount,{once:true});else mount();
})();
